package jp.tapmarker;
import java.util.*;

public class BancAutonomyTest {
 static int checks;
 static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 static float[] texture(float low){float[] f=new float[768];for(int y=0;y<16;y++)for(int x=0;x<16;x++)for(int c=0;c<3;c++)f[(y*16+x)*3+c]=low+((x+y)%2)*.18f;return f;}
 static PhaseEngine.Phase phase(String id){PhaseEngine.Phase p=new PhaseEngine.Phase();p.id=id;p.name=id;return p;}
 static PhaseEngine engine(){
  PhaseEngine e=new PhaseEngine();e.strictRuntime=true;e.windowRelative=true;
  PhaseEngine.Region top=new PhaseEngine.Region();top.id="top";top.name="heading";top.bounds=new float[]{.1f,.1f,.9f,.2f};e.regions.put(top.id,top);
  PhaseEngine.Region bottom=new PhaseEngine.Region();bottom.id="bottom";bottom.name="control";bottom.bounds=new float[]{.1f,.7f,.9f,.8f};e.regions.put(bottom.id,bottom);
  PhaseEngine.Phase stuck=phase("stuck"),ready=phase("ready"),verify=phase("verify"),end=phase("end");end.terminal=true;
  PhaseEngine.Watch input=new PhaseEngine.Watch();input.id="input";input.condition=PhaseEngine.MATCH;input.action=PhaseEngine.CENTER;input.regionId="top";input.reference=texture(.5f);input.guardIds=new String[]{"bottom"};input.guardReferences=new float[][]{texture(.6f)};input.threshold=.001f;input.nextPhase="verify";ready.watches.add(input);
  PhaseEngine.Watch confirm=PhaseEngine.copyWatch(input);confirm.id="confirm";confirm.action=PhaseEngine.WAIT;confirm.nextPhase="ready";verify.watches.add(confirm);
  e.phases.put(stuck.id,stuck);e.phases.put(ready.id,ready);e.phases.put(verify.id,verify);e.phases.put(end.id,end);e.initial="stuck";e.enter("stuck",0);return e;
 }
 static Map<String,float[]> samples(boolean ready,boolean scan){Map<String,float[]> m=new HashMap<>();m.put("top",texture(ready?.5f:.05f));m.put("bottom",texture(ready?.6f:.1f));m.put(BancAutonomy.OVERVIEW,texture(ready?.55f:.02f));if(scan)m.put(BancAutonomy.SCAN,new float[]{1});return m;}
 static final Set<String> BLOCKED=Collections.emptySet();
 static BancAutonomy.Ui ui(){return new BancAutonomy.Ui("報酬 コイン ゲット",Collections.singletonList(new BancAutonomy.Control("ゲット","claim",new float[]{.1f,.7f,.9f,.8f})));}
 static BancAutonomy.Decision review(BancAutonomy core,PhaseEngine e,boolean ready,boolean scan,long at,BancAutonomy.Ui ui){return core.review(e,samples(ready,scan),ui,at,at,BLOCKED);}
 static void prime(BancAutonomy core,PhaseEngine e,boolean ready){core.reset(0);review(core,e,ready,true,1,BancAutonomy.Ui.empty());}
 static void successfulEpisode(BancAutonomy core,PhaseEngine e,long start){
  int priorVerified=core.verified;
  e.enter("stuck",start);core.reset(start);review(core,e,false,true,start+1,ui());BancAutonomy.Decision d=review(core,e,false,true,start+3000,ui());check(d.kind==BancAutonomy.CONTROL,"readable unknown control chosen after stable observation");check(d.activation>0,"new action requires BANC activity");check(core.begin(d,e,ui(),samples(false,true),start+3000),"grounded action creates one pending episode");check(!core.begin(d,e,ui(),samples(false,true),start+3001),"one pending action per game");core.sent(start+3010);
  check(review(core,e,false,true,start+3500,ui()).kind==BancAutonomy.WAIT&&core.verified==priorVerified,"dispatch and unchanged screen do not count as success");
  check(review(core,e,true,true,start+4000,ui()).kind==BancAutonomy.WAIT,"first result frame cannot promote a skill");d=review(core,e,true,true,start+5000,ui());check(d.kind==BancAutonomy.RESYNC&&!core.pending(),"two independent anchors across two fresh result frames verified");check(core.commitResync(d,e,start+5000)&&e.current.equals("ready"),"verified action hands back to configured automaton");
 }
 public static void main(String[] args){
  PhaseEngine e=engine();BancAutonomy core=new BancAutonomy();prime(core,e,true);
  check(review(core,e,true,true,2600,BancAutonomy.Ui.empty()).kind==BancAutonomy.WAIT,"state recovery requires two fresh images");
  check(core.review(e,samples(true,true),BancAutonomy.Ui.empty(),2600,3000,BLOCKED).kind==BancAutonomy.NONE,"reused frame does not confirm recovery");
  BancAutonomy.Decision d=review(core,e,true,true,3600,BancAutonomy.Ui.empty());check(d.kind==BancAutonomy.RESYNC&&d.target.equals("ready"),"action state and matching verification state collapse to one destination");e.lastCompletedRule="prior-operation";e.sourcePhase="prior-phase";long epoch=e.epoch;
  check(core.commitResync(d,e,3600)&&e.current.equals("ready")&&e.epoch>epoch,"recovery changes current state only after evidence");check(e.lastCompletedRule.equals("prior-operation")&&e.sourcePhase.equals("prior-phase")&&e.initial.equals("stuck"),"recovery never invents action history or changes configured start");check(core.skills.isEmpty(),"observation-only recovery is not a rewarded skill");
  epoch=e.epoch;e.restartObservation(3700);check(e.epoch>epoch&&e.current.equals("ready")&&e.sourcePhase.equals("prior-phase")&&e.lastCompletedRule.equals("prior-operation"),"retry refreshes the observation epoch while preserving operation and source-state history");
  e=engine();core=new BancAutonomy();prime(core,e,true);PhaseEngine.Phase duplicate=phase("other");PhaseEngine.Watch other=PhaseEngine.copyWatch(e.rule("input"));other.id="other-action";duplicate.watches.add(other);e.phases.put(duplicate.id,duplicate);check(review(core,e,true,true,3000,BancAutonomy.Ui.empty()).kind==BancAutonomy.NONE,"visually ambiguous different destinations not arbitrated by neural score");
  e=engine();core=new BancAutonomy();e.rule("input").guardIds=new String[0];e.rule("input").guardReferences=new float[0][];e.rule("confirm").guardIds=new String[0];e.rule("confirm").guardReferences=new float[0][];prime(core,e,true);check(review(core,e,true,true,3000,BancAutonomy.Ui.empty()).kind==BancAutonomy.NONE,"one image anchor cannot resynchronize state");
  e=engine();e.regions.get("bottom").bounds=e.regions.get("top").bounds.clone();check(!BancAutonomy.strongMatch(e,e.rule("input"),samples(true,true)),"same-area guard is not independent evidence");
  e=engine();Map<String,float[]> invalid=samples(true,true);invalid.get("top")[0]=Float.NaN;check(!BancAutonomy.strongMatch(e,e.rule("input"),invalid),"nonfinite screen samples cannot pass evidence gate");
  e=engine();e.rule("input").historyRule="missing-history";e.rule("confirm").historyRule="missing-history";core=new BancAutonomy();prime(core,e,true);check(review(core,e,true,true,3000,BancAutonomy.Ui.empty()).kind==BancAutonomy.NONE,"history guards cannot be bypassed by recovery");
  e=engine();core=new BancAutonomy();prime(core,e,true);Set<String> blocked=new HashSet<>(Arrays.asList("ready","verify"));check(core.review(e,samples(true,true),BancAutonomy.Ui.empty(),3000,3000,blocked).kind==BancAutonomy.NONE,"mission journey can block return to main game");
  e=engine();core=new BancAutonomy();prime(core,e,true);core.selector.disconnectAll();review(core,e,true,true,3000,BancAutonomy.Ui.empty());check(review(core,e,true,true,4000,BancAutonomy.Ui.empty()).kind==BancAutonomy.NONE,"all graph edges cut prevents resynchronization");
  e=engine();core=new BancAutonomy();successfulEpisode(core,e,0);check(core.skills.size()==1&&!core.skills.values().iterator().next().acquired(),"one verified episode remains a candidate");successfulEpisode(core,e,10000);check(core.skills.size()==1&&core.skills.values().iterator().next().acquired(),"two consistent verified successes acquire a reusable skill");check(core.verified==2,"verified result count is distinct from dispatch count");
  e=engine();core=new BancAutonomy();core.reset(0);review(core,e,false,true,1,ui());d=review(core,e,false,true,3000,ui());check(core.begin(d,e,ui(),samples(false,true),3000),"timeout fixture begins action");core.sent(3010);check(review(core,e,false,true,18001,ui()).kind==BancAutonomy.WAIT&&!core.pending()&&core.failures==1,"unverified result times out without completing automaton");check(!core.skills.values().iterator().next().acquired(),"failed episode is never promoted");check(review(core,e,false,true,27000,ui()).kind==BancAutonomy.NONE,"same source/control attempt blocked after timeout");check(e.current.equals("stuck")&&e.lastCompletedRule.isEmpty(),"failure leaves logical state and completion history intact");
  e=engine();core=new BancAutonomy();core.reset(0);review(core,e,false,true,1,ui());d=review(core,e,false,true,3000,ui());core.begin(d,e,ui(),samples(false,true),3000);core.sent(3010);e.enter("ready",3200);check(review(core,e,true,true,4000,ui()).kind==BancAutonomy.NONE&&core.skills.isEmpty(),"late action result from old epoch discarded without training");
  e=engine();core=new BancAutonomy();e.recordingReviewRequired=true;prime(core,e,false);check(review(core,e,false,true,3000,ui()).kind==BancAutonomy.NONE,"unreviewed recording cannot be activated by autonomy");e.recordingReviewRequired=false;e.enter("end",3100);check(review(core,e,false,true,4000,ui()).kind==BancAutonomy.NONE,"explicit terminal state stays terminal");
  e=engine();core=new BancAutonomy();core.reset(0);review(core,e,false,true,1,ui());check(core.review(e,samples(false,true),ui(),1000,4000,BLOCKED).kind==BancAutonomy.NONE,"stale image cannot propose a new action");
  check(BancAutonomy.safeKind("ゲット","報酬 コイン").equals("claim"),"claim operation requires visible reward context");check(BancAutonomy.safeKind("ゲット","設定").isEmpty(),"generic get label is insufficient");check(BancAutonomy.safeKind("閉じる","購入を確認").isEmpty(),"commerce context excludes autonomy");check(BancAutonomy.safeKind("このままはじめる","ゲーム").equals("resume"),"resume named game button supported");check(BancAutonomy.safeKind("宝箱を開ける","宝箱").equals("chest"),"chest named game button supported");check(BancAutonomy.safeKind("OK","報酬").isEmpty(),"ambiguous OK never invented as an action");
  e=engine();core=new BancAutonomy();PhaseEngine.Watch input=e.rule("input");for(int i=0;i<3;i++)check(core.permitNormal(e,input,samples(true,true),i*1000),"first three unchanged transition sends allowed");check(!core.permitNormal(e,input,samples(true,true),3000),"fourth unchanged transition send held");check(!core.permitNormal(e,input,samples(true,true),3500),"cooldown prevents immediate retry");check(core.permitNormal(e,input,samples(false,true),3600),"new source screen clears unchanged-input budget");input.nextPhase=e.current;for(int i=0;i<10;i++)check(core.permitNormal(e,input,samples(true,true),4000+i),"intentional same-state game tapping is not blocked");
  BancAutonomy.Skill learned=new BancAutonomy.Skill();learned.attempts=3;learned.successes=2;learned.failures=1;learned.rewardSum=-.1;check(!learned.acquired(),"minimum success count alone cannot promote negative-reward skill");
  e=engine();core=new BancAutonomy();input=e.rule("input");input.action=PhaseEngine.CURVE;for(int i=0;i<3;i++)check(core.permitNormal(e,input,samples(true,true),i*1000),"swipe transition shares the bounded initial attempt budget");check(!core.permitNormal(e,input,samples(true,true),3000),"unchanged swipe result prevents a fourth transition input");
  e=engine();String identity=BancGraphIdentity.of(GameTarget.FARM,e);
  check(!identity.equals(BancGraphIdentity.of(GameTarget.BALLOON,e)),"farm and balloon in same app cannot share learned logic");
  check(!identity.equals(BancGraphIdentity.of(GameTarget.OMISE,e)),"distinct apps cannot share skill memory");
  e.enter("ready",12000);e.lastCompletedRule="temporary-history";check(identity.equals(BancGraphIdentity.of(GameTarget.FARM,e)),"runtime current state and observations do not invalidate graph memory");
  e.rule("input").touchPoint=new float[]{.3f,.8f};check(!identity.equals(BancGraphIdentity.of(GameTarget.FARM,e)),"editing action position creates new memory scope");
  e=engine();e.rule("input").guardReferences[0][0]+=.01f;check(!identity.equals(BancGraphIdentity.of(GameTarget.FARM,e)),"editing guard image invalidates old learned shortcuts");
  e=engine();e.rule("input").duration++;check(!identity.equals(BancGraphIdentity.of(GameTarget.FARM,e)),"editing operation duration invalidates old learned logic");
  e=engine();e.recordingReviewRequired=true;check(!identity.equals(BancGraphIdentity.of(GameTarget.FARM,e)),"unreviewed recording cannot inherit executable skills");
  e=engine();core=new BancAutonomy();core.reset(0);BancAutonomy.Ui ambiguous=new BancAutonomy.Ui("報酬 コイン ゲット",Arrays.asList(new BancAutonomy.Control("ゲット","claim",new float[]{.1f,.5f,.5f,.6f}),new BancAutonomy.Control("ゲット","claim",new float[]{.6f,.7f,.9f,.8f})));review(core,e,false,true,1,ambiguous);check(review(core,e,false,true,3000,ambiguous).kind==BancAutonomy.NONE,"two distinct claim buttons are not guessed between");
  e=engine();core=new BancAutonomy();core.reset(0);review(core,e,false,true,1,ui());core.selector.disconnectAll();check(review(core,e,false,true,3000,ui()).kind==BancAutonomy.NONE,"all BANC edges cut also prevents new UI action");
  e=engine();e.enter("ready",0);PhaseEngine.Watch hold=e.rule("input");hold.action=PhaseEngine.WAIT;hold.nextPhase="ready";hold.fallback=true;core=new BancAutonomy();core.reset(0);review(core,e,true,true,1,ui());d=review(core,e,true,true,3000,ui());check(d.kind==BancAutonomy.CONTROL,"recording-end observation can still propose an independently readable safe button");core.begin(d,e,ui(),samples(true,true),3000);core.sent(3010);Map<String,float[]> animation=samples(true,true);animation.put(BancAutonomy.OVERVIEW,texture(.02f));check(core.review(e,animation,ui(),4000,4000,BLOCKED).kind==BancAutonomy.WAIT&&core.skills.isEmpty(),"animated background in same registered state cannot earn false success credit");
  System.out.println("BancAutonomyTest: "+checks+" checks passed; deterministic runtime fixtures, Android input untested");
 }
}
